import math


def best_rational(num: int, den: int, max_den: int, side: int = 0) -> tuple[int, int]:
    if den == 0:
        raise ValueError("den == 0")
    if max_den < 1:
        raise ValueError("max_den must be at least 1")
    if side not in (-1, 0, 1):
        raise ValueError("side must be -1, 0, or 1")

    # Normalize the input rational so that the denominator is positive.
    if den < 0:
        num = -num
        den = -den

    g = math.gcd(num, den)
    a = num // g
    b = den // g
    B = max_den

    # If the reduced fraction itself is allowed, it is always the correct answer.
    if b <= B:
        return (a, b)

    # Simple continued fraction of a / b, and its convergents.
    # We use the usual convention:
    #   C_-2 = 0/1, C_-1 = 1/0, C_i = cf[i] * C_{i-1} + C_{i-2}
    aa = a
    bb = b

    cf = []
    conv_p = []
    conv_q = []

    p_prev2, q_prev2 = 0, 1
    p_prev1, q_prev1 = 1, 0

    while bb != 0:
        c = aa // bb
        p = c * p_prev1 + p_prev2
        q = c * q_prev1 + q_prev2

        cf.append(c)
        conv_p.append(p)
        conv_q.append(q)

        p_prev2, p_prev1 = p_prev1, p
        q_prev2, q_prev1 = q_prev1, q

        aa, bb = bb, aa - c * bb

    # Add an offset so that index i in conv corresponds to offset i+2:
    # p_seq[0]=C_-2, p_seq[1]=C_-1, p_seq[2]=C_0, ...
    p_seq = [0, 1] + conv_p
    q_seq = [1, 0] + conv_q

    def normalize(p: int, q: int) -> tuple[int, int]:
        if q < 0:
            p, q = -p, -q
        if p == 0:
            return (0, 1)
        d = math.gcd(abs(p), q)
        return (p // d, q // d)

    def cmp_frac(p1: int, q1: int, p2: int, q2: int) -> int:
        lhs = p1 * q2
        rhs = p2 * q1
        if lhs < rhs:
            return -1
        if lhs > rhs:
            return 1
        return 0

    def below(p: int, q: int) -> bool:
        return cmp_frac(p, q, a, b) < 0

    def above(p: int, q: int) -> bool:
        return cmp_frac(p, q, a, b) > 0

    def best_lower() -> tuple[int, int]:
        best = None

        def consider(p: int, q: int) -> None:
            nonlocal best
            if q < 1 or q > B:
                return
            p, q = normalize(p, q)
            if not below(p, q):
                return

            if best is None:
                best = (p, q)
                return

            bp, bq = best
            cmp_val = cmp_frac(p, q, bp, bq)
            if cmp_val > 0:
                best = (p, q)
            elif cmp_val == 0:
                if q < bq or (q == bq and p < bp):
                    best = (p, q)

        # All convergents that fit.
        for i in range(len(conv_q)):
            if conv_q[i] <= B:
                consider(conv_p[i], conv_q[i])

        # The best semiconvergent on each continued-fraction branch.
        for i in range(1, len(cf)):
            base_p = p_seq[i]
            base_q = q_seq[i]
            prev_p = p_seq[i + 1]
            prev_q = q_seq[i + 1]

            if prev_q == 0:
                continue

            t = (B - base_q) // prev_q
            if t < 1:
                continue
            if t > cf[i]:
                t = cf[i]

            consider(base_p + t * prev_p, base_q + t * prev_q)

        return best

    def best_upper() -> tuple[int, int]:
        best = None

        def consider(p: int, q: int) -> None:
            nonlocal best
            if q < 1 or q > B:
                return
            p, q = normalize(p, q)
            if not above(p, q):
                return

            if best is None:
                best = (p, q)
                return

            bp, bq = best
            cmp_val = cmp_frac(p, q, bp, bq)
            if cmp_val < 0:
                best = (p, q)
            elif cmp_val == 0:
                if q < bq or (q == bq and p < bp):
                    best = (p, q)

        # All convergents that fit.
        for i in range(len(conv_q)):
            if conv_q[i] <= B:
                consider(conv_p[i], conv_q[i])

        # The best semiconvergent on each continued-fraction branch.
        for i in range(1, len(cf)):
            base_p = p_seq[i]
            base_q = q_seq[i]
            prev_p = p_seq[i + 1]
            prev_q = q_seq[i + 1]

            if prev_q == 0:
                continue

            t = (B - base_q) // prev_q
            if t < 1:
                continue
            if t > cf[i]:
                t = cf[i]

            consider(base_p + t * prev_p, base_q + t * prev_q)

        return best

    def closest() -> tuple[int, int]:
        left = best_lower()
        right = best_upper()

        if left is None:
            return right
        if right is None:
            return left

        p1, q1 = left
        p2, q2 = right

        d1 = abs(p1 * b - a * q1)
        d2 = abs(p2 * b - a * q2)

        lhs = d1 * q2
        rhs = d2 * q1

        if lhs < rhs:
            return left
        if rhs < lhs:
            return right

        if q1 < q2:
            return left
        if q2 < q1:
            return right

        if p1 < p2:
            return left
        return right

    if side == -1:
        return best_lower()
    if side == 1:
        return best_upper()
    return closest()
